        Scanner input = new Scanner(System.in);
        int count = input.nextInt();
        if (count <= 11) {
            long[][] pointsArray = new long[count][5];

            for (int i = 0; i < count; i++) {
                for (int j = 0; j < 5; j++) {
                    pointsArray[i][j] = input.nextLong();
                }
            }

            long[][][] vectors = new long[count][count][5];
            for (int i = 0; i < count; i++) {
                for (int j = 0; j < count; j++) {
                    for (int k = 0; k < 5; k++) {
                        vectors[i][j][k] = pointsArray[j][k] - pointsArray[i][k];
                    }
                }
            }

            HashSet<Integer> eliminated = new HashSet<>();

            for (int i = 0; i < count; i++) {
