#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

bool equalVectors(const vector<long>& a, const vector<long>& b) {
    for (int i = 0; i < 5; i++) {
        if (a[i] != b[i]) return false;
    }
    return true;
}

bool dotProductVectors(const vector<long>& a, const vector<long>& b) {
    long long sum = 0;
    for (int i = 0; i < 5; i++) {
        sum += a[i] * b[i];
    }
    return sum > 0;
}

int main() {
    int count;
    cin >> count;
    if (count <= 11) {
        vector<vector<long>> pointsArray(count, vector<long>(5));
        for (int i = 0; i < count; i++) {
            for (int j = 0; j < 5; j++) {
                cin >> pointsArray[i][j];
            }
        }

        vector<vector<vector<long>>> vectors(count, vector<vector<long>>(count, vector<long>(5)));
        for (int i = 0; i < count; i++) {
            for (int j = 0; j < count; j++) {
                for (int k = 0; k < 5; k++) {
                    vectors[i][j][k] = pointsArray[j][k] - pointsArray[i][k];
                }
            }
        }

        unordered_set<int> eliminated;

        for (int i = 0; i < count; i++) {
            bool foundFlag = false;
            for (int j = 0; j < count; j++) {
                for (int k = 0; k < count; k++) {
                    if (i != j && i != k && !equalVectors(vectors[i][j], vectors[i][k]) && dotProductVectors(vectors[i][j], vectors[i][k])) {
                        eliminated.insert(i + 1);
                        foundFlag = true;
                        break;
                    }
                }
                if (foundFlag) break;
            }
        }

        cout << count - (int)eliminated.size() << "\n";
        for (int i = 1; i <= count; i++) {
            if (eliminated.find(i) == eliminated.end()) {
                cout << i << "\n";
            }
        }
    } else {
        cout << 0 << "\n";
    }
    return 0;
}
